// Hand-written `drizzle-orm` stub for the flowatlas fixture suite. It declares only
// what `fixtures/nest-drizzle/src` touches, shaped like the real library so that
// `resolveTypeOrigin` sees the same thing it sees on a real repo: the receiver's type
// is declared in `node_modules/drizzle-orm`, and nothing in that type names a table.
//
// That last part is the point of the fixture. A drizzle connection is one object for
// the whole schema, so the entity cannot come from a type argument the way it does for
// `Repository<Order>`; the table is an expression inside the call, and the `drizzle-orm`
// descriptor's locators are what find it.
//
// `pgTable` really lives in `drizzle-orm/pg-core` and `drizzle` in
// `drizzle-orm/node-postgres`; both are folded in here so the fixture needs a single
// stub package. `packageOfPath` answers `drizzle-orm` for either path, so folding them
// in changes nothing the adapter reads.
//
// What is deliberately not folded away is the *shape* of what `drizzle()` returns. A
// stub is allowed to declare less than the library; it is not allowed to declare a
// different kind of type, because then the fixture measures the stub instead of the
// library.

export declare class PgTable<Name extends string = string> {
  private readonly name: Name;
}

export declare const pgTable: <Name extends string>(
  name: Name,
  columns: Record<string, unknown>,
) => PgTable<Name>;

export declare const text: (name?: string) => unknown;
export declare const integer: (name?: string) => unknown;

export declare class SelectBuilder {
  from(table: PgTable): SelectBuilder;
  where(condition: unknown): SelectBuilder;
  limit(count: number): Promise<unknown[]>;
}

export declare class InsertBuilder {
  values(row: Record<string, unknown>): Promise<unknown>;
}

export declare class UpdateBuilder {
  set(row: Record<string, unknown>): UpdateBuilder;
  where(condition: unknown): Promise<unknown>;
}

export declare class DeleteBuilder {
  where(condition: unknown): Promise<unknown>;
}

export declare class Database {
  select(columns?: Record<string, unknown>): SelectBuilder;
  selectDistinct(columns?: Record<string, unknown>): SelectBuilder;
  insert(table: PgTable): InsertBuilder;
  update(table: PgTable): UpdateBuilder;
  delete(table: PgTable): DeleteBuilder;
}

/**
 * The driver's own connection, which the real library hands back alongside the
 * database so that a caller can close it or reach past the query builder.
 */
export declare class Sql {
  end(): Promise<void>;
}

/**
 * Returns an intersection, because that is what the library returns.
 *
 * The real signature is `PostgresJsDatabase<TSchema> & { $client: Sql }`, and a
 * stub that flattened it to a plain class was a different shape from the thing
 * it stood for. An intersection carries no symbol of its own, so a receiver
 * typed as one had no origin at all: no package, no descriptor, no table. The
 * fixture could not see that, because the fixture was testing the stub.
 */
export declare const drizzle: (connection?: unknown) => Database & { $client: Sql };
export declare const eq: (column: unknown, value: unknown) => unknown;
